    assign core_sipo_valid_li[i] = core_ss_valid_lo;
    assign core_sipo_data_li[i][ddr_width_lp-1:channel_width_p] = {core_ss_data_top[phy_width_lp-2:0], core_ss_data_top[phy_width_lp-1]};

