module i2c_master #(
	parameter integer DW = 3, // i2c_clk = sys_clk / (4 * ((1 << DW) + 1))
	parameter integer TW = 0, // Timeout (0 = no timeout)
	parameter integer CLOCK_STRETCH = 0
